    // whose content-range gives us no framing -- leave it false and are never
    // resumed, because there would be nothing to hold the resumed body to.
    this.resume = false
    this.start = 0
    this.end = null
    this.size = null
    this.etag = null
    this.statusCode = null
    this.headers = null
