  #onAbort

  constructor (onAbort) {
    this.#onAbort = onAbort
    this.target = null
  }

  pause () { this.target?.pause() }
  resume () { this.target?.resume() }

  abort (reason) {
    this.target?.abort(reason)
    this.#onAbort(reason)
  }

  get paused () { return this.target?.paused ?? false }
  get aborted () { return this.target?.aborted ?? false }
