'use strict'
const { createServer } = require('node:http')
const { once } = require('node:events')
const { Client, interceptors } = require('.')

async function run (name, firstResponse) {
  const chunks = []
  let requests = 0
  const server = createServer((req, res) => {
    if (requests++ === 0) {
      firstResponse(req, res)
      return
    }
    // Attacker-controlled "resume": arbitrary content that would be
    // concatenated onto what the consumer already read.
    res.writeHead(206, {
      'content-range': `bytes 4-11/12`,
      'content-length': '8'
    })
    res.end('EVILEVIL')
  })
  server.listen(0)
  await once(server, 'listening')

  const client = new Client(`http://localhost:${server.address().port}`)
    .compose(interceptors.retry({ maxRetries: 3, minTimeout: 10, maxTimeout: 10 }))

  let error = null
  let body = ''
  try {
    const res = await client.request({ method: 'GET', path: '/' })
    for await (const c of res.body) chunks.push(c)
    body = Buffer.concat(chunks).toString()
  } catch (err) {
    error = err
    body = Buffer.concat(chunks).toString()
  }
  console.log(`${name}:\n  requests=${requests} body=${JSON.stringify(body)} error=${error && (error.code || error.message)}`)
  await client.close()
  server.close()
  await once(server, 'close')
}

async function main () {
  await run('206 without content-range, truncated', (req, res) => {
    res.writeHead(206, { 'content-type': 'multipart/byteranges; boundary=X' })
    res.write('AAAA')
    setTimeout(() => res.socket.destroy(), 50)
  })

  await run('exposed error response, truncated', (req, res) => {
    res.writeHead(404, { 'content-length': '12' })
    res.write('AAAA')
    setTimeout(() => res.socket.destroy(), 50)
  })

  await run('resumable 200 with content-length, truncated', (req, res) => {
    res.writeHead(200, { 'content-length': '12' })
    res.write('AAAA')
    setTimeout(() => res.socket.destroy(), 50)
  })
}

main()

